const DATA = JSON.parse(RAW, (_k, v) => {
  if (v && typeof v === "object" && typeof v.__date__ === "string") return new Date(v.__date__);
  if (v && typeof v === "object" && Array.isArray(v.__buffer__)) return Buffer.from(v.__buffer__);
  return v;
});

const CREATE_ORDER = ["Department","User","Program","Teacher","Student","AcademicYear","Subject","Curriculum","CurriculumYear","CurriculumSemester","CurriculumCourse","CurriculumElective","SubjectTeacher","Class","Break","Assessment","Result","Announcement","StudyMaterial","StudyMaterialClass","Bookmark","Syllabus","AttendanceSession","AttendanceRecord","Notification","ProfilePrivacy","StudentSemester"];
const clientKey = (m: string) => m[0].toLowerCase() + m.slice(1);
const TABLE_NAMES = CREATE_ORDER.map((m) => '"' + m + '"').join(", ");

async function main() {
  await prisma.$executeRawUnsafe("TRUNCATE TABLE " + TABLE_NAMES + " RESTART IDENTITY CASCADE");
  for (const model of CREATE_ORDER) {
    const rows = DATA[model] ?? [];
    if (rows.length === 0) continue;
    await (prisma as any)[clientKey(model)].createMany({ data: rows });
    console.log("  seeded " + model + " " + rows.length);
  }
}

main()
  .then(() => prisma.$disconnect())
  .catch(async (e) => {
    console.error(e);
    await prisma.$disconnect();
    process.exit(1);
  });
